  "content": "1|import type { GridQueryState } from '../../../lib/appTableGridQuery';
2|
3|export type UsersListQuery = {
4|  sortBy?: string;
5|  sortDir?: 'asc' | 'desc';
6|  email?: string;
7|  full_name?: string;
8|  roles?: string;
9|  roleNames?: string;
10|  search?: string;
11|  locked?: 'true' | 'false';
12|  createdFrom?: string;
13|  createdTo?: string;
14|  updatedFrom?: string;
15|  updatedTo?: string;
16|  page?: number;
17|  pageSize?: number;
18|};
19|
20|const SORT_FIELDS = new Set(['email', 'full_name', 'created_at', 'updated_at']);
21|export const USERS_DEFAULT_PAGE_SIZE = 50;
22|export const USERS_MAX_PAGE_SIZE = 500;
23|const DEFAULT_PAGE_SIZE = USERS_DEFAULT_PAGE_SIZE;
24|const MAX_PAGE_SIZE = USERS_MAX_PAGE_SIZE;
25|
26|function parsePositiveInt(raw: unknown, fallback: number, max: number): number {
27|  const parsed = Number.parseInt(String(raw ?? ''), 10);
28|  if (!Number.isFinite(parsed) || parsed < 1) {
29|    return fallback;
30|  }
31|  return Math.min(parsed, max);
32|}
33|
34|function parseSortDir(raw: unknown): 'asc' | 'desc' | undefined {
35|  const value = String(raw ?? '').trim().toLowerCase();
36|  if (value === 'asc') return 'asc';
37|  if (value === 'desc') return 'desc';
38|  return undefined;
39|}
40|
41|function parseLockedFilter(raw: unknown): 'true' | 'false' | undefined {
42|  const value = String(raw ?? '').trim().toLowerCase();
43|  if (value === 'true' || value === 'false') {
44|    return value;
45|  }
46|  return undefined;
47|}
48|
49|export function parseUsersListQuery(raw: Record<string, unknown>): UsersListQuery {
50|  const sortBy = String(raw.sortBy ?? '').trim();
51|  const sortDir = parseSortDir(raw.sortDir ?? raw.sortDirection);
52|
53|  return {
54|    sortBy: SORT_FIELDS.has(sortBy) ? sortBy : undefined,
55|    sortDir,
56|    email: String(raw.email ?? raw.emailFilter ?? '').trim() || undefined,
57|    full_name: String(raw.full_name ?? raw.fullName ?? raw.fullNameFilter ?? '').trim() || undefined,
58|    roles: String(raw.roles ?? raw.rolesFilter ?? '').trim() || undefined,
59|    roleNames: String(raw.roleNames ?? raw.role_names ?? '').trim() || undefined,
60|    search: String(raw.search ?? raw.q ?? '').trim() || undefined,
61|    locked: parseLockedFilter(raw.locked),
62|    createdFrom: String(raw.createdFrom ?? '').trim() || undefined,
63|    createdTo: String(raw.createdTo ?? '').trim() || undefined,
64|    updatedFrom: String(raw.updatedFrom ?? '').trim() || undefined,
65|    updatedTo: String(raw.updatedTo ?? '').trim() || undefined,
66|    page: parsePositiveInt(raw.page, 1, Number.MAX_SAFE_INTEGER),
67|    pageSize: parsePositiveInt(raw.pageSize ?? raw.page_size ?? raw.limit, DEFAULT_PAGE_SIZE, MAX_PAGE_SIZE),
68|  };
69|}
70|
71|export function mapGridQueryToUsersListQuery(query: GridQueryState): UsersListQuery {
72|  const params: UsersListQuery = {};
73|
74|  if (query.sort) {
75|    params.sortBy = query.sort.columnId;
76|    params.sortDir = query.sort.direction;
77|  }
78|
79|  for (const [columnId, filter] of Object.entries(query.filters)) {
80|    if (filter.type === 'text') {
81|      if (columnId === 'email') params.email = filter.value;
82|      if (columnId === 'full_name') params.full_name = filter.value;
83|      if (columnId === 'roles') params.roles = filter.value;
84|    }
85|    if (filter.type === 'boolean' && columnId === 'locked') {
86|      if (filter.value === 'true' || filter.value === 'false') {
87|        params.locked = filter.value;
88|      }
89|    }
90|    if (filter.type === 'dateRange' && columnId === 'created_at') {
91|      params.createdFrom = filter.from ?? undefined;
92|      params.createdTo = filter.to ?? undefined;
93|    }
94|    if (filter.type === 'dateRange' && columnId === 'updated_at') {
95|      params.updatedFrom = filter.from ?? undefined;
96|      params.updatedTo = filter.to ?? undefined;
97|    }
98|  }
99|
100|  return params;
101|}
