103|export function appendUsersListParams(searchParams: URLSearchParams, query: UsersListQuery) {
104|  if (query.sortBy) searchParams.set('sortBy', query.sortBy);
105|  if (query.sortDir) searchParams.set('sortDir', query.sortDir);
106|  if (query.email?.trim()) searchParams.set('email', query.email.trim());
107|  if (query.full_name?.trim()) searchParams.set('full_name', query.full_name.trim());
108|  if (query.roles?.trim()) searchParams.set('roles', query.roles.trim());
109|  if (query.roleNames?.trim()) searchParams.set('roleNames', query.roleNames.trim());
110|  if (query.search?.trim()) searchParams.set('search', query.search.trim());
111|  if (query.locked) searchParams.set('locked', query.locked);
112|  if (query.createdFrom?.trim()) searchParams.set('createdFrom', query.createdFrom.trim());
113|  if (query.createdTo?.trim()) searchParams.set('createdTo', query.createdTo.trim());
114|  if (query.updatedFrom?.trim()) searchParams.set('updatedFrom', query.updatedFrom.trim());
115|  if (query.updatedTo?.trim()) searchParams.set('updatedTo', query.updatedTo.trim());
116|  if (query.page != null) searchParams.set('page', String(query.page));
117|  if (query.pageSize != null) searchParams.set('pageSize', String(query.pageSize));
118|}
